package com.example

import com.example.ExamQuestionHelper.QSpec

internal object BuddhismG11LiveExamPhilosophyBank {
  private const val T = "මූලික බෞද්ධ දර්ශනය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("බුදුදහමේ හරය ලෙස සැලකෙන ප්‍රධානතම ඉගැන්වීම කුමක්ද?", "චතුරාර්ය සත්‍යය", "සතර බ්‍රහ්ම විහරණ", "දස රාජධර්ම", "සතර සංග්‍රහ වස්තු", "සියලු බුදුරජාණන් වහන්සේලාගේ සාමුක්කංසික දේශනාව චතුරාර්ය සත්‍යයයි."),
    q("චතුරාර්ය සත්‍යයේ පළමු සත්‍යය වන දුක්ඛ ආර්ය සත්‍යයෙන් පැහැදිලි කරන්නේ කුමක්ද?", "සසර පැවැත්මේ දුක්ඛිත ස්වභාවය", "දුකට හේතු වන තණ්හාව", "දුක නැති කිරීමේ නිර්වාණය", "දුක නැති කිරීමේ මාර්ගය", "ජාති, ජරා, ව්‍යාධි, මරණ ආදී වශයෙන් පංච උපාදානස්කන්ධයම දුක් බව පෙන්වයි."),
    q("දුක්ඛ ආර්ය සත්‍යය පිළිබඳව අප විසින් සිදු කළ යුතු කෘත්‍යය කුමක්ද?", "පිරිසිඳ දැන ගැනීම (පරිඤ්ඤෙය්‍ය)", "ප්‍රහීණ කිරීම (පහාතබ්බ)", "සාක්ෂාත් කිරීම (සච්ඡිකාතබ්බ)", "වැඩීම (භාවේතබ්බ)", "දුක පිරිසිඳ දැනගත යුතු අතර සමුදය ප්‍රහීණ කළ යුතුය."),
    q("දුක හටගැනීමට මූලික හේතුව ලෙස දුක්ඛ සමුදය ආර්ය සත්‍යයේ දැක්වෙන්නේ කුමක්ද?", "තණ්හාව", "පංචශීලය", "සමාධිය", "අනිත්‍යතාව", "කාම, භව, විභව යන ත්‍රිවිධ තණ්හාව දුකට මුල් වේ."),
    q("දුක්ඛ සමුදය ආර්ය සත්‍යය කෙරෙහි කළ යුතු කෘත්‍යය කුමක්ද?", "ප්‍රහීණ කිරීම", "පිරිසිඳ දැන ගැනීම", "වැඩීම", "සාක්ෂාත් කිරීම", "දුකට හේතුව වූ තණ්හාව මුළුමනින්ම ප්‍රහීණ කළ යුතුය."),
    q("පංච කාම වස්තූන් කෙරෙහි ඇතිවන දැඩි ඇල්ම හඳුන්වන්නේ කුමන තණ්හාව ලෙසද?", "කාම තණ්හා", "භව තණ්හා", "විභව තණ්හා", "ධම්ම තණ්හා", "රූප, ශබ්ද, ගන්ධ, රස, ස්පර්ශ යන පංච කාමයට ඇලීම කාම තණ්හාවයි."),
    q("නැවත නැවත ඉපදීමට හා සදාකාලික පැවැත්මට ඇති ආශාව කුමන තණ්හාවද?", "භව තණ්හා", "කාම තණ්හා", "විභව තණ්හා", "රූප තණ්හා", "ශාස්වත දෘෂ්ටිය හා බැඳුණු පැවැත්මට ඇති ආශාව භව තණ්හාවයි."),
    q("මරණින් මතු පැවැත්මක් නැත යන උච්ඡේද දෘෂ්ටිය සමඟ ඇතිවන තණ්හාව කුමක්ද?", "විභව තණ්හා", "භව තණ්හා", "කාම තණ්හා", "අරූප තණ්හා", "නොපැවැත්ම පිළිබඳ ඇල්ම විභව තණ්හාව ලෙස හැඳින්වේ."),
    q("තෙවන ආර්ය සත්‍යය වන දුක්ඛ නිරෝධ ආර්ය සත්‍යය යනු කුමක්ද?", "නිර්වාණය", "සංසාරය", "පංචස්කන්ධය", "ධ්‍යානය", "තණ්හාව මුළුමනින්ම නැති කිරීමෙන් ලබන නිවන දුක්ඛ නිරෝධයයි."),
    q("දුක්ඛ නිරෝධ ආර්ය සත්‍යය පිළිබඳව කළ යුතු කෘත්‍යය කුමක්ද?", "සාක්ෂාත් කිරීම", "ප්‍රහීණ කිරීම", "පිරිසිඳ දැන ගැනීම", "වැඩීම", "නිර්වාණය ප්‍රත්‍යක්ෂයෙන් සාක්ෂාත් කර ගත යුතුය."),
    q("දුක්ඛ නිරෝධ ගාමිණී පටිපදා ආර්ය සත්‍යයෙන් දැක්වෙන්නේ කුමක්ද?", "ආර්ය අෂ්ටාංගික මාර්ගය", "දස පුණ්‍ය ක්‍රියා", "සතර සතිපට්ඨානය", "සප්ත බොජ්ඣංග", "දුක නැති කිරීමේ මධ්‍යම ප්‍රතිපදාව ආර්ය අෂ්ටාංගික මාර්ගයයි."),
    q("මධ්‍යම ප්‍රතිපදාව විසින් ප්‍රතික්ෂේප කරනු ලබන අන්ත දෙක මොනවාද?", "කාමසුඛල්ලිකානුයෝගය හා අත්තකිලමථානුයෝගය", "කුසල් හා අකුසල්", "ලෝභය හා ද්වේෂය", "සමථය හා විපස්සනාව", "අධික සැප විඳීම හා ශරීරයට දැඩි දුක් දීම යන අන්ත දෙකම නිෂ්ඵල වේ."),
    q("ආර්ය අෂ්ටාංගික මාර්ගයේ අංග අට අයත් වන ත්‍රිශික්ෂා තුන මොනවාද?", "ශීල, සමාධි, ප්‍රඥා", "දාන, ශීල, භාවනා", "ශ්‍රද්ධා, වීර්යය, සති", "මෙත්තා, කරුණා, මුදිතා", "සීල, සමාධි, ප්‍රඥා යන ත්‍රිශික්ෂාව යටතේ අෂ්ටාංගික මාර්ගය වර්ග කෙරේ."),
    q("ආර්ය අෂ්ටාංගික මාර්ගයෙන් ප්‍රඥා ශික්ෂාවට අයත් වන අංග දෙක මොනවාද?", "සම්මා දිට්ඨි හා සම්මා සංකප්ප", "සම්මා වාචා හා සම්මා කම්මන්ත", "සම්මා වායාම හා සම්මා සති", "සම්මා ආජීව හා සම්මා සමාධි", "නිවැරදි දැක්ම හා නිවැරදි කල්පනාව ප්‍රඥාවට අයත් වේ."),
    q("ආර්ය අෂ්ටාංගික මාර්ගයෙන් ශීල ශික්ෂාවට අයත් වන අංග තුන මොනවාද?", "සම්මා වාචා, සම්මා කම්මන්ත, සම්මා ආජීව", "සම්මා දිට්ඨි, සම්මා සංකප්ප, සම්මා සති", "සම්මා වායාම, සම්මා සති, සම්මා සමාධි", "සම්මා දිට්ඨි, සම්මා වාචා, සම්මා සමාධි", "වචනය, ක්‍රියාව හා ජීවිකාව සීල ශික්ෂාවට අයත් වේ."),
    q("ආර්ය අෂ්ටාංගික මාර්ගයෙන් සමාධි ශික්ෂාවට අයත් වන අංග තුන මොනවාද?", "සම්මා වායාම, සම්මා සති, සම්මා සමාධි", "සම්මා වාචා, සම්මා කම්මන්ත, සම්මා ආජීව", "සම්මා දිට්ඨි, සම්මා සංකප්ප, සම්මා වායාම", "සම්මා කම්මන්ත, සම්මා සති, සම්මා සමාධි", "උත්සාහය, සිහිය හා සිතේ එකඟතාව සමාධියට අයත් වේ."),
    q("චතුරාර්ය සත්‍යය පිළිබඳ නිවැරදි අවබෝධය හඳුන්වන්නේ කුමන මාර්ග අංගය ලෙසද?", "සම්මා දිට්ඨි", "සම්මා සංකප්ප", "සම්මා සති", "සම්මා සමාධි", "ලෝකෝත්තර සම්මා දිට්ඨිය යනු චතුරාර්ය සත්‍යාවබෝධයයි."),
    q("නෙක්ඛම්ම, අව්‍යාපාද හා අවිහිංසා යන සංකල්ප තුන අයත් වන්නේ කුමන අංගයටද?", "සම්මා සංකප්ප", "සම්මා දිට්ඨි", "සම්මා වාචා", "සම්මා කම්මන්ත", "කාමයෙන් වෙන්වීම, මෛත්‍රිය හා අවිහිංසාව නිවැරදි සංකල්පනා වේ."),
    q("බොරු, කේලාම්, පරුෂ වචන හා හිස් වචනවලින් වැළකීම අයත් වන්නේ කුමන අංගයටද?", "සම්මා වාචා", "සම්මා කම්මන්ත", "සම්මා ආජීව", "සම්මා සති", "වාචසික සුචරිතය සම්මා වාචා නම් වේ."),
    q("ප්‍රාණඝාතය, අදත්තාදානය හා කාමමිථ්‍යාචාරයෙන් වැළකීම කුමන අංගයද?", "සම්මා කම්මන්ත", "සම්මා වාචා", "සම්මා ආජීව", "සම්මා වායාම", "කායික සුචරිත තුන සම්මා කම්මන්තයට අයත් වේ."),
    q("ධාර්මික රැකියාවක නිරත වෙමින් පස් පවින් තොරව දිවි ගෙවීම කුමක්ද?", "සම්මා ආජීව", "සම්මා කම්මන්ත", "සම්මා සංකප්ප", "සම්මා සමාධි", "පංච අධාර්මික වෙළඳාම්වලින් වැළකීම සම්මා ආජීවයයි."),
    q("සතර සම්‍යක් ප්‍රධාන වීර්යය අන්තර්ගත වන්නේ කුමන මාර්ග අංගයේද?", "සම්මා වායාම", "සම්මා සති", "සම්මා සමාධි", "සම්මා සංකප්ප", "නූපන් අකුසල් නූපදවීම ආදී වීර්යය සතර සම්මා වායාමයයි."),
    q("කය, වේදනා, සිත හා ධර්ම කෙරෙහි සිහිය පිහිටුවීම කුමන මාර්ග අංගයද?", "සම්මා සති", "සම්මා සමාධි", "සම්මා දිට්ඨි", "සම්මා වායාම", "සතර සතිපට්ඨානය වැඩීම සම්මා සතියයි."),
    q("කුසල් සිතක එකඟතාව හා රූපාවචර ධ්‍යාන සතර උපදවා ගැනීම කුමක්ද?", "සම්මා සමාධි", "සම්මා සති", "සම්මා වායාම", "සම්මා සංකප්ප", "ප්‍රථම, ද්විතීය, තෘතීය, චතුර්ථ ධ්‍යාන වැඩීම සම්මා සමාධියයි."),
    q("බෞද්ධ දර්ශනයේ 'පරම සුඛය' (පරම නිෂ්ඨාව) ලෙස හැඳින්වෙන්නේ කුමක්ද?", "නිර්වාණය", "බ්‍රහ්ම ලෝකය", "තව්තිසා දෙව්ලොව", "සක්විති රජකම", "රාග, ද්වේෂ, මෝහ ක්ෂය කිරීම නිවනයි."),
    q("සෝවාන් ඵලයට පත් ආර්ය ශ්‍රාවකයා ප්‍රහීණ කරන සංයෝජන ධර්ම තුන මොනවාද?", "සක්කායදිට්ඨි, විචිකිච්ඡා, සීලබ්බතපරාමාස", "කාමරාග, පටිඝ, මාන", "උද්ධච්ච, අවිජ්ජා, රූපරාග", "විචිකිච්ඡා, මාන, අරූපරාග", "මුල් සංයෝජන තුන ප්‍රහීණ කළ සෝතාපන්න පුද්ගලයා නියත වශයෙන්ම නිවන් දකී."),
    q("කාමරාග සහ පටිඝ යන සංයෝජන දෙක මුළුමනින්ම ප්‍රහීණ කරන්නේ කුමන මාර්ග ඵලයේදීද?", "අනාගාමී ඵලයේදී", "සෝවාන් ඵලයේදී", "සකදාගාමී ඵලයේදී", "අරහත් ඵලයේදී", "අනාගාමී උතුමා නැවත කාම ලෝකයට නොපැමිණේ."),
    q("දස සංයෝජන ධර්ම සියල්ලම මුළුමනින්ම ප්‍රහීණ කළ උතුමා කවුද?", "මහරහතන් වහන්සේ", "සෝවාන් උතුමා", "සකදාගාමී උතුමා", "අනාගාමී උතුමා", "රූපරාග, අරූපරාග, මාන, උද්ධච්ච, අවිජ්ජා ඇතුළු සියලු සංයෝජන රහතුන් වහන්සේ නසති."),
    q("මිථ්‍යා දෘෂ්ටිය පිළිබඳව සඳහන් වන 'උච්ඡේද දෘෂ්ටිය' යනු කුමක්ද?", "මරණින් මතු සියල්ල කෙළවර වේ යැයි ගැනීම", "ආත්මය සදාකාලික යැයි ගැනීම", "කර්මයට විපාක ඇතැයි ගැනීම", "දෙවියන් ලොව මැවූ බව ගැනීම", "පුනර්භවය හා කර්මඵල ප්‍රතික්ෂේප කිරීම උච්ඡේදවාදයයි."),
    q("'ශාස්වත දෘෂ්ටිය' යනුවෙන් බුදුදහමේ හඳුන්වන්නේ කුමන වැරදි මතයද?", "සදාකාලික නොවෙනස්වන ආත්මයක් ඇතැයි ගැනීම", "මරණින් මතු කිසිවක් නැතැයි ගැනීම", "කිසිවකට හේතුවක් නැතැයි ගැනීම", "සියල්ල ඉබේ සිදුවේ යැයි ගැනීම", "ආත්මය නිත්‍ය සුඛ යැයි ගැනීම ශාස්වතවාදයයි."),
    q("කිසිදු හේතුවක් නොමැතිව සියල්ල ඉබේ සිදුවේ යැයි පැවසූ ෂඩ් ශාස්තෘ මතය කුමක්ද?", "අහේතුකවාදය", "නියතිවාදය", "අක්‍රියවාදය", "උච්ඡේදවාදය", "මක්ඛලී ගෝසාලගේ සංසාර ශුද්ධිවාදය අහේතුක හා නියතිවාදී මතයකි."),
    q("පුද්ගලයෙකුට තමා කරන ක්‍රියාවලින් කිසිදු පිනක් හෝ පවක් නැතැයි කීවේ කවුද?", "පූරණ කස්සප", "අජිත කේසකම්බල", "නිගණ්ඨ නාථපුත්ත", "සංජය බෙල්ලට්ඨිපුත්ත", "පූරණ කස්සපගේ අක්‍රියවාදය කර්ම විපාක ප්‍රතික්ෂේප කළේය."),
    q("සත්වයාගේ ජීවිතය ප්‍රඥාවෙන් විමසා බලා පිළිගත යුතු බව උගන්වන සූත්‍රය කුමක්ද?", "කාලාම සූත්‍රය", "වසල සූත්‍රය", "සිඟාලෝවාද සූත්‍රය", "රතන සූත්‍රය", "අන්ධ විශ්වාසයෙන් බැහැරව විමර්ශනයෙන් සත්‍යය තේරුම් ගැනීම කාලාම සූත්‍රයේ ඉගැන්වේ."),
    q("බුදුදහමේ ඉගැන්වෙන 'ඒහිපස්සිකෝ' යන ධර්ම ගුණයේ අර්ථය කුමක්ද?", "ඇවිත් බලන්න යැයි විවෘතව ආරාධනා කළ හැකි බව", "සියලු කාලයටම ගැළපෙන බව", "තමා විසින්ම දැකගත යුතු බව", "නිවනට පමුණුවන බව", "බුදුදහම විවෘත පරීක්ෂණයට ඉඩ සලසන බව මෙයින් කියවේ."),
    q("ඕනෑම කාලයකට හා සමාජයකට වෙනස් නොවී ගැළපෙන බව දැක්වෙන ධර්ම ගුණය කුමක්ද?", "අකාලිකෝ", "සන්දිට්ඨිකෝ", "ඕපනෙයිකෝ", "ස්වාක්ඛාතෝ", "අකාලික යනු කාලයට සීමා නොවී ඵල දෙන බවයි."),
    q("විඤ්ඤූ පුරුෂයන් විසින් තම තමන්ගේ නුවණින් අවබෝධ කරගත යුතු බව දැක්වෙන ධර්ම ගුණය කුමක්ද?", "පච්චත්තං වේදිතබ්බෝ විඤ්ඤූහි", "ස්වාක්ඛාතෝ", "ඒහිපස්සිකෝ", "සන්දිට්ඨිකෝ", "සෑම අයෙකුම තමා තුළින්ම සත්‍යය අත්විඳිය යුතු බව මෙයින් කියවේ."),
    q("බුදුදහමට අනුව සංසාරයේ සත්වයා බැඳ තබන ප්‍රධාන අකුසල මූල තුන මොනවාද?", "ලෝභ, ද්වේෂ, මෝහ", "අලෝභ, අදෝස, අමෝහ", "ශීල, සමාධි, ප්‍රඥා", "රූප, වේදනා, සඤ්ඤා", "රාග, ද්වේෂ, මෝහ යන තුන ත්‍රිවිධ අකුසල මූල නම් වේ."),
    q("අසංඛත ධර්මය (හේතු ප්‍රත්‍යයන්ගෙන් හට නොගත් ධර්මය) ලෙස බුදුදහමේ දැක්වෙන්නේ කුමක්ද?", "නිර්වාණය", "පංචස්කන්ධය", "චතුර්මහා භූත", "සංස්කාර", "අනෙක් සියලු සංස්කාර සංඛත වන අතර නිර්වාණය පමණක් අසංඛත වේ."),
    q("පංච නියාම ධර්ම අතරට අයත් වන කාලගුණය හා සෘතු විපර්යාස පාලනය කරන නියාමය කුමක්ද?", "උතු නියාමය", "බීජ නියාමය", "කම්ම නියාමය", "චිත්ත නියාමය", "වර්ෂාව, සුළඟ හා උෂ්ණත්වය වැනි භෞතික වෙනස්කම් උතු නියාමයට අයත් වේ."),
    q("ගසක ඇටයෙන් එම වර්ගයේම පැළයක් හටගැනීම පාලනය වන්නේ කුමන නියාම ධර්මයෙන්ද?", "බීජ නියාමය", "උතු නියාමය", "ධම්ම නියාමය", "කම්ම නියාමය", "ජීව විද්‍යාත්මක ප්‍රවේණික ලක්ෂණ බීජ නියාමය මගින් ක්‍රියාත්මක වේ."),
    q("සිතුවිලි පහළ වීමේ හා ක්‍රියාත්මක වීමේ ස්වභාවික රටාව පාලනය කරන නියාමය කුමක්ද?", "චිත්ත නියාමය", "කම්ම නියාමය", "උතු නියාමය", "බීජ නියාමය", "චිත්ත වීථි ක්‍රියාකාරිත්වය චිත්ත නියාමයට අයත් වේ."),
    q("බෝසත් කුමරු උපදින විට මහ පොළොව කම්පා වීම වැනි ධර්මතා අයත් වන නියාමය කුමක්ද?", "ධම්ම නියාමය", "කම්ම නියාමය", "උතු නියාමය", "චිත්ත නියාමය", "සාමාන්‍ය ලෝක ස්වභාවයට අයත් නොවන විශේෂ ධර්මතා ධම්ම නියාමය වේ."),
    q("ලෝකයේ සිදුවන සියලුම සිදුවීම් කර්මයෙන්ම සිදු නොවන බව දැක්වීමට බුදුරදුන් දෙසූ සූත්‍රය කුමක්ද?", "සීවක සූත්‍රය", "මංගල සූත්‍රය", "රතන සූත්‍රය", "වසල සූත්‍රය", "පිත, සෙම, වාතය හා සෘතු ආදී කරුණු අටකින් රෝග හටගන්නා බව සීවක සූත්‍රයේ එයි."),
    q("කිසියම් වස්තුවක් පිළිබඳ 'අනිත්‍ය, දුක්ඛ, අනාත්ම' යන ස්වභාවයන් හැඳින්වෙන්නේ කුමන නමකින්ද?", "ත්‍රිලක්ෂණය", "ත්‍රිශික්ෂාව", "ත්‍රිවිධ රත්නය", "ත්‍රිවිධ පුණ්‍ය ක්‍රියා", "සියලු සංස්කාර ධර්මයන්ගේ පොදු ලක්ෂණ තුන ත්‍රිලක්ෂණයයි."),
    q("බෞද්ධ සමාජයේ සාමය හා සංහිඳියාව සඳහා මූලික වන 'අවිරෝධතා' ගුණයෙන් අදහස් වන්නේ කුමක්ද?", "කිසිවෙකු සමඟ නොගැටී සමගියෙන් කටයුතු කිරීම", "සියල්ලන්ටම විරුද්ධ වීම", "ධනය රැස් කිරීම", "තනිව විසීම", "දස රාජධර්මයේ අවසාන ගුණාංගය අවිරෝධතාවයයි."),
    q("ලෝක ස්වභාවය විස්තර කරන 'අෂ්ට ලෝක ධර්මය' යටතේ අයහපත් පැතිකඩ සතර මොනවාද?", "අලාභ, අයස, නින්දා, දුක්ඛ", "ලාභ, යස, ප්‍රශංසා, සුඛ", "ජාති, ජරා, ව්‍යාධි, මරණ", "ලෝභ, ද්වේෂ, මෝහ, මාන", "සැප දුක් දෙකෙහිම නොසැලී සිටීම මංගල කරුණකි."),
    q("අෂ්ට ලෝක ධර්මය හමුවේ මහරහතන් වහන්සේ කෙනෙකු තුළ පවතින මානසික ස්ථාවරත්වය කුමක්ද?", "උපේක්ෂාව (නොසැලෙන සිත)", "දැඩි ශෝකය", "අධික සතුට", "ක්‍රෝධය", "'ඵුට්ඨස්ස ලෝකධම්මේහි චිත්තං යස්ස න කම්පති' ලෙස මංගල සූත්‍රයේ වදාළහ."),
    q("සතර මග සතර ඵල ලැබූ උතුමන් හැඳින්වෙන පොදු නාමය කුමක්ද?", "අෂ්ටාර්ය පුද්ගල මහා සංඝයා", "පෘථග්ජන පිරිස", "චතුර්විධ ආර්යයන්", "සප්ත ආර්යයන්", "සෝවාන්, සකදාගාමී, අනාගාමී, අරහත් මාර්ග හා ඵලලාභීන් අටදෙනා මෙයට අයත් වේ."),
    q("නිර්වාණය පිළිබඳව සඳහන් වන 'සෝපාදිසේස නිබ්බාන ධාතු' යනු කුමක්ද?", "පංචස්කන්ධය පවතිද්දීම කෙලෙස් නැසූ අවස්ථාව", "පරිනිර්වාණයෙන් පසු අවස්ථාව", "සෝවාන් වූ අවස්ථාව", "ධ්‍යාන ලැබූ අවස්ථාව", "ජීවමාන රහතන් වහන්සේලා අත්විඳින නිවන් සුවය සෝපාදිසේස නිබ්බාන ධාතුවයි."),
    q("රහතන් වහන්සේගේ පරිනිර්වාණයෙන් පසු උපාදානස්කන්ධයද නිරුද්ධ වීම හඳුන්වන්නේ කෙසේද?", "අනුපාදිසේස නිබ්බාන ධාතු", "සෝපාදිසේස නිබ්බාන ධාතු", "සචේතනික නිර්වාණය", "අරූපාවචර සමාපත්තිය", "ස්කන්ධ පරිනිර්වාණය අනුපාදිසේස නිබ්බාන ධාතුවයි."),
    q("බුදුදහමේ ඉගැන්වෙන 'අභිඥා' හෙවත් විශිෂ්ට ඥාන සංඛ්‍යාව කොපමණද?", "ෂඩ් අභිඥා (සයකි)", "ත්‍රිවිද්‍යා (තුනකි)", "දස බල (දහයකි)", "චතුර් අභිඥා (සතරකි)", "ඉද්ධිවිධ, දිබ්බසෝත, චේතෝපරිය, පුබ්බේනිවාස, දිබ්බචක්ඛු, ආසවක්ඛය ෂඩ් අභිඥාවයි."),
    q("ලෞකික සියලු වස්තූන් කෙරෙහි 'මමය මාගේය' යන හැඟීම ඇතිවීම කුමන ධර්මයද?", "සක්කායදිට්ඨිය", "විචිකිච්ඡාව", "උද්ධච්චය", "පටිඝය", "ආත්ම දෘෂ්ටිය හෙවත් සක්කායදිට්ඨිය සෝවාන් මඟින් ප්‍රහීණ වේ."),
    q("බුදු, දහම්, සඟ හා කර්ම ඵල පිළිබඳව සිතේ පවතින අවිශ්වාසය හා සැකය කුමක්ද?", "විචිකිච්ඡාව", "සීලබ්බතපරාමාසය", "කාමච්ඡන්දය", "ථීනමිද්ධය", "සැකය නිරාකරණය කර ගැනීම සඳහා ධර්ම ශ්‍රවණය හා ප්‍රශ්න කිරීම වැදගත් වේ."),
    q("නිවන් මඟට නොගැළපෙන වැරදි ව්‍රත සමාදානවලින් විමුක්තිය පැතීම හඳුන්වන්නේ කෙසේද?", "සීලබ්බතපරාමාසය", "සක්කායදිට්ඨිය", "අවිජ්ජාව", "භවරාගය", "ගෝව්‍රත, අජව්‍රත ආදී නිෂ්ඵල ව්‍රතවල එල්බ සිටීම සීලබ්බතපරාමාසයයි."),
    q("සත්වයා සසරින් මිදීමට අවශ්‍ය වන ඉන්ද්‍රිය ධර්ම පහ (පංච ඉන්ද්‍රිය) මොනවාද?", "සද්ධා, විරිය, සති, සමාධි, පඤ්ඤා", "චක්ඛු, සෝත, ඝාණ, ජිව්හා, කාය", "දාන, සීල, භාවනා, ඛන්ති, මෙත්තා", "ලෝභ, දෝස, මෝහ, මාන, දිට්ඨි", "පංච ඉන්ද්‍රියන් වැඩී බලවත් වූ විට පංච බල බවට පත්වේ."),
    q("බෞද්ධ දර්ශනයට අනුව 'පුද්ගලයා' යනු කුමක්ද?", "නාම හා රූප ධර්මයන්ගේ එකතුවකි", "නොවෙනස්වන ආත්මයකි", "භෞතික ශරීරය පමණි", "දෙවියන්ගේ නිර්මාණයකි", "පංචස්කන්ධය හෙවත් නාමරූප සන්තතිය පුද්ගලයා ලෙස ව්‍යවහාර කෙරේ."),
    q("දේව නිර්මාණවාදය බුදුදහම විසින් ප්‍රතික්ෂේප කරනු ලබන්නේ කුමන න්‍යායකට අනුවද?", "පටිච්චසමුප්පාද හේතුඵල න්‍යායට", "ශාස්වතවාදී න්‍යායට", "අහේතුකවාදී න්‍යායට", "භෞතිකවාදී න්‍යායට", "සියල්ල හේතු ප්‍රත්‍ය සම්බන්ධයෙන් හටගන්නා බව බුදුදහම පෙන්වයි."),
    q("මනුෂ්‍ය භවයක් ලැබීම ඉතා දුර්ලභ බව පෙන්වීමට බුදුරදුන් දෙසූ උපමාව කුමක්ද?", "කණ කැස්බෑවා විය සිදුරෙන් අහස බැලීම", "අහසේ තරු ගණන් කිරීම", "මහ මුහුදේ ජලය මැනීම", "පහන් දැල්ල නිවී යාම", "දුර්ලභ මිනිසත් බව අප්‍රමාදව කුසලයේ යෙදවිය යුතු බව වදාළහ."),
    q("පංච බල ධර්ම අතරින් සිත සැහැල්ලු කරන ශ්‍රද්ධාව සමබර කරන බලය කුමක්ද?", "පඤ්ඤා බලය", "විරිය බලය", "සති බලය", "සමාධි බලය", "ශ්‍රද්ධාව හා ප්‍රඥාවත්, වීර්යය හා සමාධියත් සමබරව පැවතිය යුතුය."),
    q("මහරහතන් වහන්සේ තුළ අලුතින් සසර ගමන ඇති කරන කර්ම රැස් නොවන්නේ ඇයි?", "තණ්හා හා අවිද්‍යා ප්‍රහීණ කර ඇති බැවින්", "කිසිදු ක්‍රියාවක් නොකරන බැවින්", "දේව ආරක්ෂාව ඇති බැවින්", "සිරුර අහිමි බැවින්", "රහතුන් වහන්සේ කරන ක්‍රියා 'ක්‍රියා සිත්' පමණක් වන අතර භවයට බීජ නොවේ."),
    q("නිවන සාක්ෂාත් කර ගැනීමට ඇති ඒකායන මාර්ගය ලෙස සතිපට්ඨාන සූත්‍රයේ දැක්වෙන්නේ කුමක්ද?", "සතර සතිපට්ඨානය", "සතර ඉර්දිපාද", "සතර සංග්‍රහ වස්තු", "සතර බඹ විහරණ", "'ඒකායනෝ අයං භික්ඛවේ මග්ගෝ' ලෙස සතර සතිපට්ඨානය වදාළහ."),
    q("පංච ඉන්ද්‍රියන්ට අරමුණු හමුවීමේදී ඒවාට ඇලීම හෝ ගැටීම නොවී සිහියෙන් සිටීම කුමක්ද?", "ඉන්ද්‍රිය සංවරය", "ආහාරයේ මත්තඤ්ඤුතාව", "ජාගරියානුයෝගය", "ප්‍රත්‍යවේක්ෂාව", "ඇස, කන ආදී ඉන්ද්‍රියන් සංවර කර ගැනීම ශීලයේ ආරක්ෂාවයි."),
    q("ආර්ය සත්‍යය හතර පිළිවෙළින් අවබෝධ කිරීමේදී මුලින්ම අවබෝධ වන්නේ කුමක්ද?", "දුක්ඛ ආර්ය සත්‍යය", "දුක්ඛ සමුදය", "දුක්ඛ නිරෝධය", "දුක්ඛ නිරෝධ ගාමිණී පටිපදාව", "දුක හඳුනාගත් විට එහි හේතුව, නැති කිරීම හා මාර්ගය වැටහේ."),
    q("සෝවාන්, සකදාගාමී, අනාගාමී යන මාර්ග ඵලලාභීන් තිදෙනා හඳුන්වන පොදු නම කුමක්ද?", "සේඛ පුද්ගලයන්", "අසේඛ පුද්ගලයන්", "පෘථග්ජන පුද්ගලයන්", "කල්‍යාණ පෘථග්ජනයන්", "තවදුරටත් හික්මිය යුතු බැවින් සේඛ නම් වන අතර රහතුන් වහන්සේ අසේඛ නම් වේ."),
    q("සකදාගාමී ඵලයට පත් උතුමා නැවත කාම ලෝකයට පැමිණෙන්නේ කී වතාවක්ද?", "එක් වතාවක් පමණි", "සත් වතාවකි", "දෙවතාවකි", "කිසිදා නොපැමිණේ", "කාමරාග හා පටිඝ තුනී කළ සකදාගාමී උතුමා එක් වරක් පමණක් මෙලොවට ආපසු එයි."),
    q("සෝවාන් ඵලයට පත් පුද්ගලයෙකු උපරිම වශයෙන් තවත් කී වරක් ඉපිද නිවන් දකීද?", "සත් වරකට නොවැඩි වාර ගණනකි", "එක් වරකි", "සිය වරකි", "දහස් වරකි", "සෝවාන් වූ උතුමා සතර අපායේ නූපදින අතර උපරිම භව හතක් ඇතුළත රහත් වේ."),
    q("ධර්මය කෙරෙහි ඇතිවන අචල විශ්වාසය හඳුන්වන පාලි වචනය කුමක්ද?", "අවෙච්චප්පසාදය", "අමූලිකා ශ්‍රද්ධාව", "මිථ්‍යා දෘෂ්ටිය", "උද්ධච්චය", "බුදු, දහම්, සඟ ගුණ නුවණින් දැන ඇතිවන නොසැලෙන ශ්‍රද්ධාව ආකාරවතී ශ්‍රද්ධාවයි."),
    q("අන්ධ ලෙස කරුණු විමසීමකින් තොරව ඇති කරගන්නා ශ්‍රද්ධාව කුමක්ද?", "අමූලිකා ශ්‍රද්ධාව", "ආකාරවතී ශ්‍රද්ධාව", "ප්‍රඥා ශ්‍රද්ධාව", "ඔක්කප්පනා ශ්‍රද්ධාව", "බුදුදහම අගය කරන්නේ නුවණින් විමසා ඇතිකරගන්නා ආකාරවතී ශ්‍රද්ධාවයි."),
    q("අධික සැප විඳීමේ ජීවන රටාව හඳුන්වන්නේ කුමන නමකින්ද?", "කාමසුඛල්ලිකානුයෝගය", "අත්තකිලමථානුයෝගය", "මජ්ඣිමා පටිපදාව", "සල්ලේඛ පටිපදාව", "හීන, ග්‍රාම්‍ය, අනාර්ය, අනර්ථකර ලෙස බුදුරදුන් මෙය හැඳින්වූහ."),
    q("ශරීරයට දැඩි වධ හිංසා දෙමින් විමුක්තිය සෙවීමේ අන්තය කුමක්ද?", "අත්තකිලමථානුයෝගය", "කාමසුඛල්ලිකානුයෝගය", "මජ්ඣිමා පටිපදාව", "ආර්ය පර්යේෂණය", "දුක්ඛ, අනාර්ය, අනර්ථකර ලෙස මෙම අන්තය දැක්වේ."),
    q("කිසිදු පුද්ගලයෙකුට අසමාන කළ නොහැකි උතුම්ම ධනය කුමක් බව ආලවක සූත්‍රයේ එයිද?", "ශ්‍රද්ධාව", "රන් රිදී", "බලය", "උගත්කම", "'සද්ධීධ විත්තං පුරිසස්ස සෙට්ඨං' යනුවෙන් ශ්‍රද්ධාව ශ්‍රේෂ්ඨ බව දේශනා කළහ."),
    q("තමන් විසින්ම සිත දමනය කර පාලනය කර ගැනීමේ වැදගත්කම කියවෙන බුදු වදන කුමක්ද?", "අත්තා හි අත්තනෝ නාථෝ", "සබ්බේ සත්තා භවන්තු සුඛිතත්තා", "අප්පමාදෝ අමතපදං", "නහි වේරේන වේරාණි", "තමාට තමාම පිහිට වන බවත් සිත දමනය කළ යුතු බවත් මෙයින් කියවේ."),
    q("කෙනෙකු තමන් අනිත්‍ය බව නොදැක සැමදා ජීවත් වේ යැයි සිතීම කුමන විපල්ලාසයද?", "නිත්‍ය සංඥාව", "සුඛ සංඥාව", "ආත්ම සංඥාව", "සුභ සංඥාව", "අනිත්‍ය දේ නිත්‍ය ලෙස ගැනීම සතර විපල්ලාසයන්ගෙන් එකකි."),
    q("මනුෂ්‍ය ජීවිතයේ දුක්වලින් 'පියේහි විප්පයෝගෝ දුක්ඛෝ' යන්නෙහි අර්ථය කුමක්ද?", "ප්‍රියයන්ගෙන් වෙන් වීම දුකකි", "අප්‍රියයන් හා එක්වීම දුකකි", "කැමති දේ නොලැබීම දුකකි", "ලෙඩ වීම දුකකි", "දුක්ඛ ආර්ය සත්‍යය විස්තර කිරීමේදී මෙම ස්වභාවික දුක් දැක්වේ."),
    q("'අප්පියේහි සම්පයෝගෝ දුක්ඛෝ' යන පාඨයේ නිවැරදි අර්ථය කුමක්ද?", "අප්‍රියයන් හා එක්වීම දුකකි", "ප්‍රියයන්ගෙන් වෙන් වීම දුකකි", "මරණය දුකකි", "ජරාවට පත්වීම දුකකි", "නොකැමති පුද්ගලයන් හා අරමුණු සමඟ එක්වීම දුකක් බව දැක්වේ."),
    q("'යම්පිච්ඡං න ලභති තම්පි දුක්ඛං' යන්නෙන් අදහස් වන්නේ කුමක්ද?", "කැමති දේ නොලැබීම දුකකි", "වයසට යාම දුකකි", "රෝගී වීම දුකකි", "උපත දුකකි", "ආශා කරන දේ නොලැබෙන විට සිතේ ඇතිවන දුක මෙයින් විස්තර කෙරේ."),
    q("සංස්කාර ධර්මයන්ගේ උපත, පැවැත්ම හා නැතිවීම යන අවස්ථා තුන හඳුන්වන්නේ කුමන නමින්ද?", "උප්පාද, ඨිති, භංග", "ජාති, ජරා, මරණ", "සීල, සමාධි, ප්‍රඥා", "ලෝභ, ද්වේෂ, මෝහ", "ක්ෂණයක් පාසා සියලු සංස්කාරයෝ හටගෙන, පැවතී, බිඳී යති."),
    q("බෞද්ධ දර්ශනයට අනුව 'සම්‍යක් දෘෂ්ටිය' (ලෞකික සම්මා දිට්ඨිය) යනු කුමක්ද?", "දසවස්තුක සම්මා දිට්ඨිය", "චතුරාර්ය සත්‍ය අවබෝධය", "ධ්‍යාන සමාපත්ති ලැබීම", "පෙර ජාති දැකීම", "දානයේ විපාක ඇත, මව්පියන්ට සැලකීමේ විපාක ඇත ආදිය පිළිගැනීම ලෞකික සම්මා දිට්ඨියයි."),
    q("සංසාරයේ සත්වයාට නිවන් දැකීමට ඇති ප්‍රධාන බාධක දෙක ලෙස බුදුරදුන් දෙසුවේ මොනවාද?", "අවිද්‍යාව හා භව තණ්හාව", "දුප්පත්කම හා රෝග", "බිය හා ලැජ්ජාව", "කාමය හා ක්‍රෝධය", "අවිද්‍යාව නැමැති අන්ධකාරය හා තණ්හාව නැමැති බැම්ම සසර දිගු කරයි."),
    q("පටිච්චසමුප්පාදය අනුලෝම වශයෙන් විමසීමෙන් පැහැදිලි වන්නේ කුමන ආර්ය සත්‍යයද?", "දුක්ඛ සමුදය ආර්ය සත්‍යය", "දුක්ඛ නිරෝධ ආර්ය සත්‍යය", "මධ්‍යම ප්‍රතිපදාව", "අනාත්ම සත්‍යය", "දුක හටගන්නා ආකාරය අනුලෝම පටිච්චසමුප්පාදයෙන් දැක්වේ."),
    q("පටිච්චසමුප්පාදය පටිලෝම වශයෙන් විමසීමෙන් පැහැදිලි වන්නේ කුමන ආර්ය සත්‍යයද?", "දුක්ඛ නිරෝධ ආර්ය සත්‍යය", "දුක්ඛ සමුදය ආර්ය සත්‍යය", "ශාස්වත දෘෂ්ටිය", "උච්ඡේද දෘෂ්ටිය", "අවිද්‍යාව නිරුද්ධ වීමෙන් දුක නිරුද්ධ වන අයුරු පටිලෝමයෙන් පැහැදිලි වේ."),
    q("බුදුරදුන් 'මම සතර සත්‍යය පරිවර්ත තුනකින් හා ආකාර දොළොසකින් අවබෝධ කළෙමි' යැයි වදාළේ කුමන සූත්‍රයේද?", "ධම්මචක්කප්පවත්තන සූත්‍රයේ", "සතිපට්ඨාන සූත්‍රයේ", "මංගල සූත්‍රයේ", "කාලාම සූත්‍රයේ", "තිපරිවට්ටං ද්වාදසාකාරං යනුවෙන් ප්‍රථම දේශනාවේදී වදාළ සේක."),
    q("නිවැරදි භාවනා ක්‍රම තුළින් ත්‍රිවිධ සික්ඛා සම්පූර්ණ කර ගැනීමට ඉවහල් වන ධර්ම මාර්ගය කුමක්ද?", "සප්ත විසුද්ධිය", "සතර ඉර්දිපාද", "සතර සංග්‍රහ වස්තු", "පංච ශීලය", "සීල විසුද්ධියේ සිට ඥානදස්සන විසුද්ධිය දක්වා සප්ත විසුද්ධිය පවතී."),
    q("සප්ත විසුද්ධියේ පළමු පියවර වන්නේ කුමක්ද?", "සීල විසුද්ධිය", "චිත්ත විසුද්ධිය", "දිට්ඨි විසුද්ධිය", "මග්ගාමග්ග ඥානදස්සන විසුද්ධිය", "පිරිසිදු ශීලය මත සමාධිය හා ප්‍රඥාව ගොඩනැගේ."),
    q("සංසාර චක්‍රය ගොඩනැගෙන මූලික ධර්මතා දෙක වන අවිද්‍යාව හා තණ්හාව හැඳින්වෙන්නේ කෙසේද?", "වට්ට මූල දෙක", "නිවන් දොරටු දෙක", "අන්ත දෙක", "ත්‍රිලක්ෂණය", "පටිච්චසමුප්පාදයේ මුල් පුරුක් ලෙස අවිද්‍යාව හා තණ්හාව ක්‍රියා කරයි."),
    q("බුදුදහමේ ඉගැන්වෙන 'හිරි' සහ 'ඔත්තප්ප' යන දෙවැදෑරුම් ධර්මතා හඳුන්වන්නේ කුමන නමින්ද?", "ලෝකපාලක ධර්ම", "සතර බ්‍රහ්ම විහරණ", "පංච නීවරණ", "අෂ්ට ලෝක ධර්ම", "පවට ඇති ලැජ්ජාව හා බිය සමාජ සදාචාරය රකින ලෝකපාලක ධර්ම (දේව ධර්ම) වේ."),
    q("බෞද්ධ සමාජයේ සියලු සත්වයන් කෙරෙහි තිබිය යුතු 'හිරි' යන්නෙහි අර්ථය කුමක්ද?", "පව් කිරීමට ඇති ආත්ම ලැජ්ජාව", "පව් කිරීමට ඇති බිය", "දන් දීමට ඇති කැමැත්ත", "ඉවසීමේ ගුණය", "තමා කෙරෙහි ගෞරවයෙන් පාපයෙන් වැළකීම හිරි නම් වේ."),
    q("'ඔත්තප්ප' යනුවෙන් හඳුන්වන්නේ කුමක්ද?", "පාප ක්‍රියාවලින් ලැබෙන විපාකයට ඇති බිය", "පාපයට ඇති ලැජ්ජාව", "රාගය", "ක්‍රෝධය", "අන් අයගෙන් ලැබෙන නින්දාවට හා අපාය දුකට බියෙන් පවින් වැළකීම ඔත්තප්පයයි."),
    q("තමාගේ සිතේ කෙලෙස් සංසිඳී සත්‍යය අවබෝධ වීම හඳුන්වන ධර්ම ගුණය කුමක්ද?", "සන්දිට්ඨිකෝ", "අකාලිකෝ", "ඒහිපස්සිකෝ", "ඕපනෙයිකෝ", "මේ ආත්මයේදීම ප්‍රත්‍යක්ෂයෙන් අත්විඳිය හැකි බව සන්දිට්ඨික ගුණයයි."),
    q("තම සිත තුළට පමුණුවාගෙන පුරුදු පුහුණු කළ යුතු නිවනට පමුණුවන ගුණය කුමක්ද?", "ඕපනෙයිකෝ", "ස්වාක්ඛාතෝ", "සන්දිට්ඨිකෝ", "අකාලිකෝ", "ධර්මය තම ජීවිතයට ළං කරගෙන නිවනට යොමු වීම ඕපනෙයික ගුණයයි."),
    q("සියලු දේ 'මේ ආකාරයෙන්ම වේ' යැයි වෙනස් නොවන සත්‍ය ස්වභාවය හඳුන්වන්නේ කෙසේද?", "තථතාව (අවිතථතාව)", "අනිත්‍යතාව", "මෝහය", "විපල්ලාසය", "පටිච්චසමුප්පාදයේ ලක්ෂණයක් ලෙස තථතා, අවිතථතා දැක්වේ."),
    q("බෞද්ධ දර්ශනයට අනුව 'විද්‍යාව' (විජ්ජා) යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "චතුරාර්ය සත්‍යාවබෝධය", "තාරකා විද්‍යාව", "රසායන විද්‍යාව", "ජ්‍යොතිෂ විද්‍යාව", "අවිද්‍යාව දුරු කරන ත්‍රිවිද්‍යා හා සත්‍යාවබෝධය බුදුදහමේ විද්‍යාවයි.")
  )
}
